fun rigText(key:String,language:String):String {
 val t=rigToolKeys.indexOf(key);if(t>=0)return rigToolRows[language]?.split('|')?.get(t) ?: key
 if(key=="Copy object")return mapOf("ru" to "Копировать предмет","be" to "Капіяваць прадмет","fr" to "Copier l’objet","de" to "Objekt kopieren","es" to "Copiar objeto","it" to "Copia oggetto","zh" to "复制物体","ja" to "物体を複製","ko" to "물체 복사")[language] ?: key
 val e=extraKeys.indexOf(key);if(e>=0)return extraRows[language]?.split('|')?.get(e) ?: key
 val i=rigKeys.indexOf(key);if(i>=0)return rigRows[language]?.split('|')?.get(i) ?: key
 val j=rigJoints.indexOf(key);if(j>=0)return (translatedJoints[language] ?: jointNames[language] ?: jointNames.getValue("en")).split('|')[j]
 return translate(key,language)
}
/** Rig editor words reached through the general dictionary (a plain Text of an English key): null when the key is not a rig term. */
fun rigTranslation(key:String,language:String):String? {
    val t=rigToolKeys.indexOf(key);if(t>=0)return rigToolRows[language]?.split('|')?.get(t) ?: key
    val e=extraKeys.indexOf(key);if(e>=0)return extraRows[language]?.split('|')?.get(e) ?: key
    val i=rigKeys.indexOf(key);if(i>=0)return rigRows[language]?.split('|')?.get(i) ?: key
    return null
}
